import { test, expect } from '@playwright/test';

test.describe('Login Loading Spinner', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/login');
  });

  test('should display loading spinner during login request', async ({ page }) => {
    await page.getByLabel('Username').fill('testuser');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Login' }).click();

    const spinner = page.getByText('Loading...'); // Assuming 'Loading...' is the text of the spinner
    await expect(spinner).toBeVisible();
  });

  test('should hide loading spinner after login request completes', async ({ page }) => {
    await page.getByLabel('Username').fill('testuser');
    await page.getByLabel('Password').fill('password123');
    await page.getByRole('button', { name: 'Login' }).click();

    const spinner = page.getByText('Loading...');
    await expect(spinner).toBeVisible();

    // Simulate waiting for the login request to complete
    await page.waitForTimeout(2000); // Adjust timeout as necessary

    await expect(spinner).toBeHidden();
  });
});
